[506]="山中何事？松花酿酒，春水煎茶",
[507]="劝君莫作独醒人，烂醉花间应有数",
[508]="称庆源深流福厚，天精储粹干星斗",
[509]="春节建筑",
[510]="苑中珍木元自奇，黄金作叶白银枝",
[511]="刻木为头丝作尾，金镀眼睛银帖齿",
[512]="唤起湘累歌未了，石狮舞罢松风晓",
[513]="爆竹声残天未晓，金炉细爇沉烟",
[514]="金橘圆嫩籽红香,满园丛林手自翻",
[515]="炉气朝成缑岭云，银灯夜作华亭月",
[516]="台上灯红莲叶密，眉间毫白黛痕销",
[517]="爆竹声中人未睡。共道今宵守岁",
[518]="凤曲登歌调令序，龙雩集舞泛祥风",
